// commonMain — logic sharing: UI-agnostic state holder, native UIs consume it
class CartViewModel(private val cart: CartRepository) {
    private val _state = MutableStateFlow(CartState())
    val state: StateFlow<CartState> = _state

    fun add(itemId: String) {
        cart.add(itemId)
        _state.value = CartState(total = cart.total(), count = cart.count())
    }
}

data class CartState(val total: Double = 0.0, val count: Int = 0)

// commonMain — UI sharing, only if the team decided to go there
@Composable
fun CheckoutButton(viewModel: CartViewModel, onClick: () -> Unit) {
    val state by viewModel.state.collectAsState()
    Button(onClick = onClick) {
        Text("Checkout — \u0024${state.total}")
    }
}

