// Registration: server supplies publicKeyCredentialCreationOptions
val createRequest = CreatePublicKeyCredentialRequest(
    requestJson = serverPasskeyCreationChallenge
)
val created = credentialManager.createCredential(createRequest) as PublicKeyCredential
server.storePublicKey(created.registrationResponseJson)

// Sign-in: challenge -> getCredential -> verify server-side
val getRequest = GetCredentialRequest(
    listOf(
        GetPublicKeyCredentialOption(requestJson = serverPasskeyRequestOptions),
        GetPasswordOption(),
    )
)
val result = credentialManager.getCredential(activity, getRequest)
when (val credential = result.credential) {
    is PublicKeyCredential -> server.verify(credential.authenticationResponseJson)
    is PasswordCredential -> server.signInWithPassword(credential.id, credential.password)
    else -> Unit
}

val status = HealthConnectClient.getSdkStatus(
    context, "com.google.android.apps.healthdata"
)
if (status != HealthConnectClient.SDK_AVAILABLE) {
    showInstallHealthConnect()
    return
}
val client = HealthConnectClient.getOrCreate(
    context, "com.google.android.apps.healthdata"
)

val required = listOf(
    HealthPermission.getReadPermission(StepsRecord::class),
    HealthPermission.getReadPermission(HeartRateRecord::class),
)
val granted = client.permissionController.getGrantedPermissions()
if (granted.containsAll(required).not()) {
    val contract = createRequestPermissionResultContract()
    launch(contract, required) { result -> handle(result) }
}

val response = client.readRecords(
    ReadRecordsRequest(
        recordType = StepsRecord::class,
        timeRangeFilter = TimeRangeFilter.between(startOfDay, endOfDay)
    )
)
val totalSteps = response.records.sumOf { it.count }

val analysis = ImageAnalysis.Builder()
    .setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST)
    .setTargetResolution(Size(1280, 720))
    .build()
    .also {
        it.setAnalyzer(cameraExecutor, ImageAnalysis.Analyzer { imageProxy ->
            try {
                processFrame(imageProxy.image, imageProxy.imageInfo.rotationDegrees)
            } finally {
                imageProxy.close()   // a leaked frame stalls the whole pipeline
            }
        })
    }

val preview = Preview.Builder().build()
cameraProvider.bindToLifecycle(
    lifecycleOwner, CameraSelector.DEFAULT_BACK_CAMERA, preview, analysis
)

// Camera2 interop: force an underlying CaptureRequest key per use case
Camera2Interop.Extender(preview).setCaptureRequestOption(
    CaptureRequest.CONTROL_AF_MODE, CameraMetadata.CONTROL_AF_MODE_CONTINUOUS_PICTURE
)
